export const getConflictScheduling = async (courts: any[], dates: string[], view: string) => {
  const scheduling = await getConflictScheduling_service(dates)
  let hasDuplicate;
  if (view === 'day') {
    hasDuplicate = courts.map(c => ({
      court: c.id,
      conflict: hasDuplicates(scheduling.filter(s => s.courts.includes(c.id)).map(s => s.slots).flat()),
      slot: scheduling.filter(s => s.courts.includes(c.id)).map(s => s.slots).flat()
    }))
  } else {
    hasDuplicate = dates.map((d: any) => ({
      date: d,
      court: courts.map(c => ({
        court: c.id,
        conflict: hasDuplicates(scheduling.filter(s => s.date === d && s.courts.includes(c.id)).map(s => s.slots).flat()),
        slot: scheduling.filter(s => s.date === d && s.courts.includes(c.id)).map(s => s.slots).flat()
      })),
      conflict: courts.map(c => ({
        court: c.id,
        conflict: hasDuplicates(scheduling.filter(s => s.date === d && s.courts.includes(c.id)).map(s => s.slots).flat()),
        slot: scheduling.filter(s => s.date === d && s.courts.includes(c.id)).map(s => s.slots).flat()
      })).map(c => c.conflict)
    }))
  }
  const allFalse = (array: boolean[]): boolean => {
    return array.some(item => item === true);
  }
  // console.log(hasDuplicate)
  // console.log(hasDuplicate.map(h => h.conflict).flat())
  return allFalse(hasDuplicate.map(h => h.conflict).flat())
}

export const searchBooking = async (filter: any) => {
