  const venue = useVenueStore().venue
  let query: any = db.collection('venues').doc(venue.id).collection('services').doc('booking').collection('scheduling');

  if (filter.user) {
    query = query.where('user', '==', filter.user);
  }
  if (filter.status) {
    query = query.where('status', '==', filter.status);
  }
  if (filter.payment) {
    query = query.where('transaction.payment', '==', filter.payment);
