export const filterScheduling_service = async (filter: any) => {
  const venue = useVenueStore().venue
  let query: any = db.collection('venues').doc(venue.id).collection('services').doc('booking').collection('scheduling');

  if (filter.user) {
    query = query.where('user', '==', filter.user);
  }
  if (filter.status) {
    query = query.where('status', '==', filter.status);
  }
  if (filter.payment) {
    query = query.where('transaction.payment', '==', filter.payment);
  }
  if (filter.courts !== 'Todos') {
    query = query.where('courts', 'array-contains', filter.courts.id);
  }

  // Ejecutar el query
  const querySnapshot = await query.get();
  return querySnapshot.docs.map((doc: any) => ({...doc.data(), id: doc.id}));
}

